BEGIN;CREATE OR REPLACE FUNCTION office_private.inst_reports(w uuid,action text,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a date;b date;rt text;report_title text;bid uuid;rid uuid;ver bigint;snap jsonb;inflow numeric;outflow numeric;cnt bigint;BEGIN IF action='create_report' THEN IF NOT office_private.inst_cap(w,'reports') THEN RAISE EXCEPTION 'Reports capability required' USING ERRCODE='42501';END IF;rt:=p->>'report_type';IF NOT office_private.inst_cap(w,office_private.inst_report_cap(rt)) THEN RAISE EXCEPTION 'Report type capability denied' USING ERRCODE='42501';END IF;report_title:=p->>'title';a:=NULLIF(p->>'period_start','')::date;b:=NULLIF(p->>'period_end','')::date;bid:=coalesce(NULLIF(p->>'branch_id','')::uuid,office_private.inst_actor_branch(w));IF rt NOT IN('finance','governance','compliance','assets','programmes') OR a IS NULL OR b IS NULL OR a>b OR report_title IS NULL OR length(report_title) NOT BETWEEN 1 AND 200 OR(bid IS NOT NULL AND NOT office_private.inst_scope(w,bid)) THEN RAISE EXCEPTION 'Invalid report request' USING ERRCODE='22023';END IF;IF p->>'idempotency_key' IS NULL OR p->>'idempotency_key'!~ '^[0-9a-fA-F-]{36}$' THEN RAISE EXCEPTION 'Report idempotency_key required' USING ERRCODE='22023';END IF;IF EXISTS(SELECT 1 FROM public.office_institutions_reports q WHERE q.workspace_id=w AND q.created_by=auth.uid() AND q.title=report_title AND q.period_start=a AND q.period_end=b AND q.report_type=rt) THEN SELECT q.id,q.version INTO rid,ver FROM public.office_institutions_reports q WHERE q.workspace_id=w AND q.created_by=auth.uid() AND q.title=report_title AND q.period_start=a AND q.period_end=b AND q.report_type=rt ORDER BY q.created_at DESC LIMIT 1;RETURN jsonb_build_object('id',rid,'version',ver,'status','existing');END IF;SELECT coalesce(sum(CASE WHEN l.kind='contribution' THEN l.amount WHEN l.kind='reversal' THEN-l.amount ELSE 0 END),0),coalesce(sum(CASE WHEN l.kind='payment' THEN l.amount ELSE 0 END),0),count(*) INTO inflow,outflow,cnt FROM public.office_institutions_ledger l WHERE l.workspace_id=w AND l.posted_on BETWEEN a AND b AND(bid IS NULL OR l.branch_id=bid) AND(office_private.inst_actor_branch(w) IS NULL OR l.branch_id=office_private.inst_actor_branch(w));snap:=jsonb_build_object('report_type',rt,'period_start',a,'period_end',b,'inflow',inflow,'outflow',outflow,'net',inflow-outflow,'ledger_entry_count',cnt,'record_counts',jsonb_build_object('organizations',(SELECT count(*) FROM public.office_institutions_records z WHERE z.workspace_id=w AND z.resource='organizations' AND(bid IS NULL OR z.data->>'branch_id'=bid::text) AND(office_private.inst_actor_branch(w) IS NULL OR z.data->>'branch_id'=office_private.inst_actor_branch(w)::text)),'programmes',(SELECT count(*) FROM public.office_institutions_records z WHERE z.workspace_id=w AND z.resource='programmes' AND(bid IS NULL OR z.data->>'branch_id'=bid::text) AND(office_private.inst_actor_branch(w) IS NULL OR z.data->>'branch_id'=office_private.inst_actor_branch(w)::text)),'assets',(SELECT count(*) FROM public.office_institutions_records z WHERE z.workspace_id=w AND z.resource='assets' AND(bid IS NULL OR z.data->>'branch_id'=bid::text) AND(office_private.inst_actor_branch(w) IS NULL OR z.data->>'branch_id'=office_private.inst_actor_branch(w)::text))));INSERT INTO public.office_institutions_reports(workspace_id,report_type,period_start,period_end,title,branch_id,snapshot,created_by) VALUES(w,rt,a,b,report_title,bid,snap,auth.uid()) RETURNING id,version INTO rid,ver;INSERT INTO public.office_institutions_audit(workspace_id,actor_id,resource,action,entity_id,purpose,metadata) VALUES(w,auth.uid(),'reports','create_report',rid,'report',jsonb_build_object('report_type',rt,'period_start',a,'period_end',b));RETURN jsonb_build_object('id',rid,'version',ver,'status','created');ELSIF action='export_report' THEN rid:=COALESCE(NULLIF(p->>'id',''),NULLIF(p->>'report_id',''))::uuid;IF rid IS NULL OR NULLIF(p->>'expected_version','')::bigint IS NULL OR (p->>'expected_version')::bigint<1 THEN RAISE EXCEPTION 'Exact report id and expected version required' USING ERRCODE='22023';END IF;IF p->>'purpose' IS NULL OR p->>'purpose' NOT IN('internal_review','compliance_review') OR NOT office_private.inst_cap(w,'reports') THEN RAISE EXCEPTION 'Report export denied' USING ERRCODE='42501';END IF;SELECT version,to_jsonb(q) INTO ver,snap FROM public.office_institutions_reports q WHERE q.workspace_id=w AND q.id=rid AND office_private.inst_cap(w,office_private.inst_report_cap(q.report_type)) AND q.version=(p->>'expected_version')::bigint AND(office_private.inst_actor_branch(w) IS NULL OR q.branch_id=office_private.inst_actor_branch(w));IF ver IS NULL THEN RAISE EXCEPTION 'Report not accessible' USING ERRCODE='42501';END IF;INSERT INTO public.office_institutions_audit(workspace_id,actor_id,resource,action,entity_id,purpose,metadata) VALUES(w,auth.uid(),'reports','export_report',rid,p->>'purpose',jsonb_build_object('version',ver));RETURN jsonb_build_object('id',rid,'version',ver,'purpose',p->>'purpose','status','exported','row',snap);ELSE RAISE EXCEPTION 'Unknown report action' USING ERRCODE='22023';END IF;END $$;REVOKE ALL ON FUNCTION office_private.inst_reports(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.office_institutions_read(uuid,text,jsonb,integer,integer) TO authenticated;DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='office_private' AND left(p.proname,5)='inst_' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f.signature); END LOOP; END $$;REVOKE ALL ON FUNCTION public.office_institutions_command(uuid,text,jsonb),public.office_institutions_read(uuid,text,jsonb,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.office_institutions_command(uuid,text,jsonb),public.office_institutions_read(uuid,text,jsonb,integer,integer) TO authenticated;COMMIT;
